# Extra unique content per city (EN + NL), three more cities and fitting packages. Executed inside build.py's namespace.
CITY_TEXT.update({
    "Leiden": ("Leiden is a university city between Amsterdam and Den Haag, with canals, old almshouses and a lively centre. Whether you live here or are staying for work or a conference, our masseuses come to your hotel or home.",
               "Your masseuse travels from Amsterdam to Leiden and brings everything she needs. You choose the massage and the masseuse, and we arrange the rest in the chat."),
    "Heemskerk": ("Heemskerk lies in Kennemerland, north of Haarlem and close to the dunes and the beach. It is a quiet place to live or to stay, and our masseuses come to your home or hotel there.",
                  "An erotic massage at home in Heemskerk is easy to arrange. Tell us your address and the time you prefer, and your masseuse travels to you from Amsterdam."),
    "Vianen": ("Vianen is an old town on the river Lek, just south of Utrecht. Many people stay here for work or on their way through the country, and our masseuses come to your hotel or home.",
               "Your masseuse travels from Amsterdam to Vianen. You choose the massage and the masseuse, and one message in the chat is enough to arrange it."),
})
NL_CITY.update({
    "Leiden": ("Leiden is een universiteitsstad tussen Amsterdam en Den Haag, met grachten, oude hofjes en een levendig centrum. Of u hier woont of er verblijft voor werk of een congres, onze masseuses komen naar uw hotel of naar u thuis.",
               "Uw masseuse reist vanuit Amsterdam naar Leiden en neemt alles mee wat zij nodig heeft. U kiest de massage en de masseuse, en wij regelen de rest in de chat."),
    "Heemskerk": ("Heemskerk ligt in Kennemerland, ten noorden van Haarlem en dicht bij de duinen en het strand. Het is een rustige plek om te wonen of te verblijven, en onze masseuses komen er bij u thuis of in uw hotel.",
                  "Een erotische massage aan huis in Heemskerk is eenvoudig geregeld. Geef uw adres en het gewenste tijdstip door, en uw masseuse reist vanuit Amsterdam naar u toe."),
    "Vianen": ("Vianen is een oud stadje aan de Lek, net ten zuiden van Utrecht. Veel mensen verblijven hier voor hun werk of op doorreis, en onze masseuses komen naar uw hotel of naar u thuis.",
               "Uw masseuse reist vanuit Amsterdam naar Vianen. U kiest de massage en de masseuse, en één bericht in de chat is genoeg om het te regelen."),
})
