PKG_NAME_EN = {p[1]: p[2] for p in PACKAGES}


def city_more(name, nl=False):
    h, about, tip = CITY_MORE[name][1 if nl else 0]
    ids = CITY_MORE[name][2]
    chips = "".join(f'<li><a href="/nl/pakketten/{i}/">{E(PKG_NL[i][0])}</a></li>' if nl else f'<li><a href="/packages/{i}/">{E(PKG_NAME_EN[i])}</a></li>' for i in ids)
    if nl:
        pk = (f'<h2>Pakketten die bij {E(name)} passen</h2><p>Drie pakketten die goed passen bij een bezoek in {E(name)}. Het tarief voor een pakket in {E(name)} bevestigen wij in de chat.</p><ul class="chips">{chips}'
              '<li><a href="/nl/pakketten/">Alle pakketten</a></li></ul>'
              f'<p>Nieuw bij ons? Lees hoe een <a href="/nl/erotische-massage-aan-huis/">erotische massage aan huis</a> verloopt.</p>')
    else:
        pk = (f'<h2>Packages that suit {E(name)}</h2><p>Three packages that fit well with a visit in {E(name)}. We confirm the rate for a package in {E(name)} in the chat.</p><ul class="chips">{chips}'
              '<li><a href="/packages/">All packages</a></li></ul>'
              f'<p>New to this? Read how an <a href="/outcall-massage-amsterdam/">outcall massage</a> works.</p>')
    return f"<h2>{E(h)}</h2><p>{E(about)}</p><p>{E(tip)}</p>" + pk


def city_girls(name, k):
    """A different selection of masseuses per city, so every profile gets links and city pages differ."""
    i = [c for _, c in CITIES].index(name) * 7 % len(MASSEUSES)
    return (MASSEUSES + MASSEUSES)[i:i + k]
